export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"A elaboração da proposta pedagógica cabe:","alternativas":["Ao conselho tutelar.","Só à Secretaria.","À escola, com participação dos professores e da comunidade.","Ao Ministério da Educação."],"correta":2,"explicacao":"É incumbência da escola, segundo a LDB."},{"pergunta":"Um bom plano anual da Secretaria tem:","alternativas":["Apenas o orçamento.","Só o calendário.","Dez prioridades.","No máximo três prioridades, com metas e prazos."],"correta":3,"explicacao":"Poucas prioridades permitem foco."},{"pergunta":"Uma criança sem documentos no ato da matrícula:","alternativas":["É encaminhada a outra cidade.","Fica sem vaga.","É matriculada, e a documentação é regularizada depois.","Aguarda o ano seguinte."],"correta":2,"explicacao":"O direito à educação vem primeiro."},{"pergunta":"A data de referência do Censo Escolar é:","alternativas":["O último dia do ano.","Definida por cada escola.","O primeiro dia de aula.","A última quarta-feira de maio."],"correta":3,"explicacao":"Os dados orientam a distribuição de recursos."},{"pergunta":"Com recursos do dinheiro direto na escola, deve-se:","alternativas":["Comprar de parente do diretor.","Seguir o plano aprovado e fazer pesquisa de preços.","Pagar sem nota.","Guardar o dinheiro."],"correta":1,"explicacao":"Plano, pesquisa, nota e prestação de contas."},{"pergunta":"A alimentação escolar:","alternativas":["É direito de todos os alunos e não é usada como prêmio ou punição.","É só para quem paga.","Dispensa nutricionista.","Pode ser retirada como castigo."],"correta":0,"explicacao":"É direito do aluno."},{"pergunta":"Para ler um resultado de avaliação, deve-se:","alternativas":["Olhar a tendência, a distribuição por nível e a participação.","Comparar com a escola mais rica.","Fazer ranking.","Olhar só a média de um ano."],"correta":0,"explicacao":"A média sozinha engana."},{"pergunta":"Escolas com resultados mais baixos devem receber:","alternativas":["Menos atenção.","Mais presença e apoio da Secretaria.","Punição.","O mesmo de todas."],"correta":1,"explicacao":"Apoio diferenciado reduz desigualdades."}];
